-- FamilyRepository.getReport
select
  f."id" as "familyId",
  f."name" as "familyName",
  (
    select
      count(*)::int
    from
      "family_member" m
    where
      m."familyId" = f."id"
  ) as "members",
  (
    select
      count(*)::int
    from
      "asset" a
      join "family_member" m on m."userId" = a."ownerId"
    where
      m."familyId" = f."id"
      and a."deletedAt" is null
  ) as "assets",
  (
    select
      count(*)::int
    from
      "family_person" fp
    where
      fp."familyId" = f."id"
  ) as "people",
  (
    select
      count(*)::int
    from
      "family_person" fp
    where
      fp."familyId" = f."id"
      and fp."name" != ''
  ) as "namedPeople",
  (
    select
      count(*)::int
    from
      "family_person" fp
    where
      fp."familyId" = f."id"
      and fp."birthDate" is not null
  ) as "peopleWithBirthDate",
  (
    select
      count(*)::int
    from
      "asset_face" af
      join "asset" a on a."id" = af."assetId"
      join "family_member" m on m."userId" = a."ownerId"
    where
      m."familyId" = f."id"
      and af."deletedAt" is null
  ) as "faces",
  (
    select
      count(*)::int
    from
      "asset_face" af
      join "asset" a on a."id" = af."assetId"
      join "family_member" m on m."userId" = a."ownerId"
    where
      m."familyId" = f."id"
      and af."deletedAt" is null
      and af."personGroupId" is not null
  ) as "facesWithPerson"
from
  "family" f
where
  f."id" = $1

-- FamilyRepository.clearPrivateCovers
with
  stale as (
    select
      p."ownerId",
      p."personGroupId",
