      and pm."familyId" = $1
      join "family_person" fp on fp."personGroupId" = p."personGroupId"
      and fp."familyId" = $2
    where
      (
        p."faceAssetId" is not null
        or p."thumbnailPath" != ''
      )
      and not exists (
        select
          1
        from
          "asset_face" sf
          join "asset" sa on sa."id" = sf."assetId"
          join "family_member" sm on sm."userId" = sa."ownerId"
          and sm."familyId" = $3
        where
          sf."id" = "p"."faceAssetId"
          and sf."personGroupId" = "p"."personGroupId"
          and sf."deletedAt" is null
          and sf."isVisible" is true
          and sa."deletedAt" is null
          and sa."visibility" in ('timeline', 'archive')
      )
  ),
  cleared as (
    update "person"
    set
      "faceAssetId" = null,
      "thumbnailPath" = ''
    from
      stale
    where
      "person"."ownerId" = stale."ownerId"
      and "person"."personGroupId" = stale."personGroupId"
    returning
      1
  )
select
  "thumbnailPath"
from
  stale
where
  "thumbnailPath" != ''

-- FamilyRepository.getPeopleWithoutCover
select
  "person"."ownerId",
  "person"."personGroupId",
  "cover"."faceId"
from
  "person"
  inner join "family_person" on "family_person"."personGroupId" = "person"."personGroupId"
  inner join lateral (
    select
      "asset_face"."id" as "faceId"
    from
      "asset_face"
      inner join "asset" on "asset"."id" = "asset_face"."assetId"
      inner join "family_member" on "family_member"."userId" = "asset"."ownerId"
      and "family_member"."familyId" = $1
    where
      "asset_face"."personGroupId" = "person"."personGroupId"
      and "asset_face"."deletedAt" is null
      and "asset_face"."isVisible" = $2
      and "asset"."deletedAt" is null
      and "asset"."visibility" in ('timeline', 'archive')
    order by
      (
        "asset_face"."boundingBoxX2" - "asset_face"."boundingBoxX1"
      ) * (
        "asset_face"."boundingBoxY2" - "asset_face"."boundingBoxY1"
      ) desc,
      "asset_face"."id"
    limit
      $3
  ) as "cover" on true
where
  "family_person"."familyId" = $4
  and not exists (
    select
    from
      "person" as "covered"
    where
      "covered"."personGroupId" = "person"."personGroupId"
      and "covered"."faceAssetId" is not null
      and exists (
        select
          1
        from
          "asset_face" sf
          join "asset" sa on sa."id" = sf."assetId"
          join "family_member" sm on sm."userId" = sa."ownerId"
          and sm."familyId" = $5
        where
          sf."id" = "covered"."faceAssetId"
          and sf."personGroupId" = "covered"."personGroupId"
          and sf."deletedAt" is null
          and sf."isVisible" is true
          and sa."deletedAt" is null
          and sa."visibility" in ('timeline', 'archive')
      )
  )

